example.code:
class Order < ApplicationRecord belongs_to :customer has_many :items, class_name: "OrderItem", dependent: :destroy
enum status: { pending: 0, paid: 1, shipped: 2, cancelled: 3 }, _prefix: true
validates :total_cents, numericality: { greater_than_or_equal_to: 0 }
scope :recent, -> { where("created_at >= ?", 30.days.ago) } scope :paid, -> { where.not(paid_at: nil) } scope :for_user, ->(user) { where(customer_id: user.customer_id) }
def cancel! transaction do update!(status: :cancelled, cancelled_at: Time.current) items.each(&:release_inventory!) end end end
